public static class CustomNode
{
    /// <summary>Greets someone by name and writes the greeting to the log.</summary>
    /// <param name="name">Who to greet.</param>
    /// <returns>The greeting.</returns>
    [Node("Greeting")]
    public static string Greet(string name, NodeContext context)
    {
        var greeting = $"Hello, {name}";
        context.Log(greeting);
        return greeting;
    }
}

public static class CustomNode
{
    /// <summary>Whether the motion sensor sees motion now.</summary>
    /// <param name="motionSensor">The motion sensor; only binary sensors can be wired or picked here.</param>
    /// <returns>True while the sensor is on.</returns>
    [Node("Motion now")]
    public static bool Run(BinarySensorEntity motionSensor) => motionSensor.State == BinarySensorState.On;
}

